import * as model from './domain.mjs';
import {metrics,compare} from '../measurement/metrics.mjs';
import {label,reasonOptions,reviewFields,ackScenario,outcomeOptions,sponsorshipMarkup,funnelMarkup,certificateMarkup,personaFor,nameFor,ownerLabel,meaningfulDraft,characterCount,nextActionValue} from './ui.mjs';
import * as product from './product.mjs';
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=model.createSession(),page='join',currentId=null,editingId=null,queueId=null,modalOpen=false,ackDialogId=null,connectionError=false,snapshot=null;
const ackScenarios=new Map();
const qCurrent=()=>state.questions.find(q=>q.question_id===currentId);
const format=value=>value===null?'N/A':Number(value.toFixed(2))+'%';
function ackLabel(q){if(q.acknowledgement==='success')return 'Demo acknowledgement recorded';if(q.acknowledgement==='failed')return q.wallet_decision==='off_chain'?'Continued off-chain after a failed attempt':'Acknowledgement failed · Your question is saved';if(q.acknowledgement==='skipped')return 'Continued off-chain';return 'Optional acknowledgement not recorded';}
function preview(q){return '<div class="question-preview">'+esc(q.text.length>160?q.text.slice(0,160)+'…':q.text)+'</div>'+(q.text.length>160?'<details><summary>Show full question</summary><div class="full-question">'+esc(q.text)+'</div></details>':'');}
function certificateButtons(questions){return questions.filter(q=>q.acknowledgement==='success').map(q=>'<button class="button text-action" data-action="certificate" data-id="'+q.question_id+'">Participation acknowledgement · '+esc(q.text.slice(0,55))+(q.text.length>55?'…':'')+'</button>').join('');}
const panel=body=>'<article class="panel">'+body+'</article>';
function notify(message){$('#notice').textContent=message;}
function ownQuestions(){return state.questions.filter(q=>q.canonical_participant_id===state.active_participant_id);}
function notebook(){
  const p=model.participant(state),m=metrics(state,{includeQA:true});
  $('#identity').innerHTML=product.profile(p);$('#identity').setAttribute('aria-label',p?'Choose participant · '+nameFor(p):'Choose participant');
  const values=[['Canonical participant ID',p?.canonical_participant_id||'Not selected'],['Registered canonical people',new Set(state.registrations.map(r=>r.canonical_participant_id)).size],['Invitation',p?label(p.invitation_status):'Not selected'],['KYC (demo)',p?label(p.kyc_demo_status):'Not selected'],['Wallet (demo)',p&&state.wallet_connections.includes(p.canonical_participant_id)?'Connected':'Not connected'],['Eligible disclosure viewers',m.disclosure_viewers],['Accepted / qualified questions',m.accepted_questions+' / '+m.qualified_questions],['Qualified people',m.qualified_participants],['Live QA conversion (tiny synthetic sample)',format(m.qualified_conversion)],['Demo attempts / real TXs',m.ack_attempts+' / '+m.real_transactions],['Explicit abandonments',state.events.filter(e=>e.event_type==='disclosure_abandoned').length]];
  $('#facts').innerHTML=values.map(([a,b])=>'<div><dt>'+esc(a)+'</dt><dd>'+esc(b)+'</dd></div>').join('');
  $('#event-log').textContent=JSON.stringify(state.events.slice(-15).reverse(),null,2);$('#raw-live').textContent=JSON.stringify(state,null,2);
}
function render({focusMain=true}={}){
  const p=model.participant(state);let content='';
  const mode=page==='queue'?'reviewer':page==='dashboard'?'measurement':'participant';
  const signpost=$('#mode-indicator');signpost.dataset.mode=mode;signpost.textContent=mode==='reviewer'?'Reviewer mode · Decisions and operational follow-up':mode==='measurement'?'Measurement mode · Synthetic snapshot and separate live QA':'Participant mode · Suncrest community review';
  document.querySelectorAll('.tabs [data-action]').forEach(button=>{if(button.dataset.action===({participant:'journey',reviewer:'queue',measurement:'dashboard'})[mode])button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});
  if(page==='join')content=product.homepage();
  if(page==='eligibility')content=product.eligibility(state,p,ownQuestions());
  if(page==='disclosure')content=product.disclosure(p,state.drafts[p.canonical_participant_id]);
  if(page==='question'){const draft=state.drafts[p.canonical_participant_id]||{text:'',section_id:''};content=product.questionForm(draft,editingId,Object.hasOwn(state.drafts,p.canonical_participant_id));}
  if(page==='saved')content=product.saved();
  if(page==='confirmation')content=product.confirmation(state,qCurrent(),preview(qCurrent()),ackLabel(qCurrent()))+certificateButtons([qCurrent()]);
  if(page==='ack-result')content=product.ackResult(state,qCurrent(),preview(qCurrent()));
  if(page==='done')content=panel('<span class="success-mark" aria-hidden="true">✓</span><h1>Thank you, '+esc(personaFor(p).first)+'.</h1><p>You have '+ownQuestions().length+' saved question'+(ownQuestions().length===1?'':'s')+'. Your question review and follow-up are independent of acknowledgement.</p><div class="actions"><button class="button" data-action="journey">View your participation</button><button class="button secondary" data-action="queue">View reviewer queue</button></div>'+certificateButtons(ownQuestions()));
  if(page==='queue')content=reviewQueue();
  if(page==='dashboard')content=dashboard();
  $('#main').innerHTML=content;notebook();if(!modalOpen&&focusMain)$('#main').focus(page==='join'?{preventScroll:true}:undefined);
}
function reviewQueue(){
  if(!state.questions.length)return panel('<span class="eyebrow">REVIEWER WORKSPACE</span><h1>A useful conversation starts with a question.</h1><p>No questions have been submitted in this session. Begin in Participant Journey. The experiment snapshot is separate.</p>');
  const q=state.questions.find(q=>q.question_id===queueId)||state.questions.at(-1);queueId=q.question_id;
  const person=model.participant(state,q.canonical_participant_id),topic=model.SECTIONS.find(s=>s.id===q.disclosure_section_id);
  return panel('<span class="eyebrow">REVIEWER WORKSPACE · HUMAN-CONTROLLED DECISIONS</span><h1>Give the question a clear next step.</h1><p>Assess the evidence gap, not the participant’s sentiment. Wallet and identity-verification status do not determine qualification.</p><label for="review-question">Saved question</label><select id="review-question">'+state.questions.map(x=>'<option value="'+x.question_id+'"'+(q===x?' selected':'')+'>'+esc(nameFor(model.participant(state,x.canonical_participant_id)))+' — '+esc(label(x.review_status))+' · '+esc(x.text.slice(0,65))+'</option>').join('')+'</select><div class="queue-card"><div class="reviewer-person"><img class="avatar" src="assets/'+personaFor(person).portrait+'.svg" alt=""><div><strong>'+esc(nameFor(person))+'</strong><span>'+esc(topic.title)+' · Version '+q.version+'</span></div></div>'+preview(q)+'<div class="question-status-grid"><section><span class="eyebrow">QUESTION REVIEW</span><p>'+esc(label(q.review_status))+'</p></section><section><span class="eyebrow">ACKNOWLEDGEMENT</span><p>'+esc(ackLabel(q))+'</p></section><section><span class="eyebrow">FOLLOW-UP</span><p>'+esc(label(q.followup_status))+(q.followup_owner==='Unassigned'?'':' · '+esc(ownerLabel(q.followup_owner)))+'</p></section></div></div><form id="review-form" data-id="'+q.question_id+'">'+reviewFields(q)+'<p id="review-feedback" class="form-feedback" role="status" aria-live="polite" tabindex="-1"></p></form>'+(q.review_status==='qualified'?'<form id="followup-form" data-id="'+q.question_id+'"><h2>Operational follow-up</h2><div class="row"><div><label for="followup-status">Follow-up status</label><select id="followup-status">'+['unassigned','triaged','response_pending','addressed'].map(s=>'<option value="'+s+'"'+(q.followup_status===s?' selected':'')+'>'+label(s)+'</option>').join('')+'</select></div><div><label for="followup-owner">Owner</label><select id="followup-owner"><option value=""'+(q.followup_owner==='Unassigned'?' selected':'')+'>Choose a reviewer</option>'+['Synthetic operations reviewer','Synthetic engineering reviewer'].map(owner=>'<option value="'+owner+'"'+(q.followup_owner===owner?' selected':'')+'>'+ownerLabel(owner)+'</option>').join('')+'</select></div></div><label for="next-action">Next action</label><input id="next-action" maxlength="300" placeholder="e.g. Request source evidence from the project team" value="'+esc(nextActionValue(state,q))+'"><p class="small">This is a local operating scenario. No project contact or response is sent.</p><button class="button secondary" type="submit">Save follow-up</button><p id="followup-feedback" class="form-feedback" role="status" aria-live="polite" tabindex="-1"></p></form>':'')+'<details class="technical-evidence"><summary>Technical Evidence · Canonical review, revision and acknowledgement history</summary><pre>'+esc(JSON.stringify({question_id:q.question_id,canonical_participant_id:q.canonical_participant_id,version:q.version,disclosure_section_id:q.disclosure_section_id,review_status:q.review_status,review_reason:q.review_reason,review_history:q.review_history,revisions:q.revisions,attempts:state.ack_attempts.filter(a=>a.question_id===q.question_id)},null,2))+'</pre></details><button class="button text-action" data-action="show-current">Return to participant question</button>');
}
function dashboard(){const c=compare(snapshot),live=metrics(state,{includeQA:true});return panel(`<span class="eyebrow">IMMUTABLE SYNTHETIC EXPERIMENT SNAPSHOT</span><h1>Qualified contribution is the outcome.</h1><p>Illustrative email fixtures only. These are not observed users, forecasts, causal estimates or statistically significant findings. Live clicks below never change this snapshot.</p><section class="variant-guide" aria-labelledby="variants-title"><h2 id="variants-title">Synthetic, unsent email variants</h2><p><strong>Control:</strong> Generic invitation to review the disclosure and ask a question.</p><p><strong>Variant:</strong> Invitation emphasizes asking a specific question and seeing review status / next action.</p><p class="small">Both use the same disclosure and wallet/KYC policy. No email was sent; these fixtures do not establish a causal winner.</p></section>${funnelMarkup('Snapshot funnel · pooled synthetic records',c.pooled)}<div class="metric-grid"><div class="metric"><strong>${format(c.control.qualified_conversion)}</strong><span>Control · ${c.control.qualified_participants}/${c.control.disclosure_viewers} qualified viewers</span></div><div class="metric"><strong>${format(c.variant.qualified_conversion)}</strong><span>Variant · ${c.variant.qualified_participants}/${c.variant.disclosure_viewers} qualified viewers</span></div><div class="metric"><strong>${format(c.pooled.qualified_conversion)}</strong><span>Pooled · ${c.pooled.qualified_participants}/${c.pooled.disclosure_viewers}</span></div><div class="metric"><strong>+${c.absolute_pp}pp</strong><span>Absolute illustration</span></div><div class="metric"><strong>+${format(c.relative_improvement)}</strong><span>Relative illustration</span></div><div class="metric"><strong>${c.pooled.real_transactions}</strong><span>Real blockchain transactions</span></div></div><div class="table-wrap"><table><caption>Derived from canonical records, same cohort and time window</caption><thead><tr><th>Metric</th><th>Control</th><th>Variant</th><th>Pooled</th></tr></thead><tbody>${[['Invitations','invited'],['Eligible disclosure viewers','disclosure_viewers'],['Question submitters','question_submitters'],['Accepted questions','accepted_questions'],['Qualified questions','qualified_questions'],['Qualified participants','qualified_participants'],['Pending review','pending_questions'],['Needs clarification','clarification_questions'],['Excluded questions','excluded_questions'],['Invitation → qualified %','invitation_to_qualified'],['Question qualification %','question_qualification_rate'],['Duplicate registration attempts','duplicate_registration_attempts'],['Demo acknowledgement attempts','ack_attempts'],['Demo successes','ack_successes'],['Sponsored successes','sponsored_successes']].map(([label,key])=>`<tr><td>${label}</td>${[c.control,c.variant,c.pooled].map(x=>`<td>${key.endsWith('rate')||key==='invitation_to_qualified'?format(x[key]):x[key]}</td>`).join('')}</tr>`).join('')}</tbody></table></div><details class="technical-evidence"><summary>Technical Evidence</summary><h3>Snapshot calculations and raw fixture links</h3><pre>${esc(JSON.stringify(c,null,2))}</pre><p><a href="../data/experiment.synthetic.json">Full JSON</a> · <a href="../data/participants.synthetic.csv">Participants CSV</a> · <a href="../data/questions.synthetic.csv">Questions CSV</a> · <a href="../measurement/README.md">Formulas / exclusions</a></p></details><div class="notice">Formula: distinct eligible canonical disclosure viewers with ≥1 currently qualified question / distinct eligible canonical disclosure viewers. Repeated aliases, repeated opens and multiple qualified questions do not add people. QA fixtures are excluded. Submission, qualification, demo acknowledgements and real transactions are separate.</div><section class="live-qa" aria-labelledby="live-title"><h2 id="live-title">Live QA sandbox · separate records</h2><div class="notice warning"><strong>Tiny synthetic sample — not an experiment result.</strong> Even 100% live QA conversion may mean only one qualified person out of one eligible viewer. It is not evidence of real-user value, causal lift or statistical significance. Live invitations are preconfigured eligible fixtures, not sent emails.</div>${funnelMarkup('Live QA funnel · separate synthetic records',live)}<p>Qualified conversion ${format(live.qualified_conversion)} = ${live.qualified_participants}/${live.disclosure_viewers}; ${live.accepted_questions} accepted questions, ${live.qualified_questions} qualified questions; ${live.ack_attempts} demo attempts; ${live.real_transactions} real transactions. Zero denominator is N/A.</p><details class="technical-evidence"><summary>Technical Evidence</summary><h3>Live QA calculation output</h3><pre>${esc(JSON.stringify(live,null,2))}</pre></details></section>`);}
function rememberAckScenario(){const scenario=ackScenario(ackScenarios,qCurrent());if($('#connect-outcome')){scenario.connect=$('#connect-outcome').value;scenario.ack=$('#ack-outcome').value;scenario.expanded=$('#ack-scenarios').open;}return scenario;}
function displayAckDialog(id){
  ackDialogId=id;modalOpen=true;
  for(const other of ['ack','sponsorship','kyc'])if(other!==id&&$('#'+other).open)$('#'+other).close();
  if(!$('#'+id).open)$('#'+id).showModal();
}
function renderAck(){
  const q=qCurrent(),p=model.participant(state),scenario=ackScenario(ackScenarios,q),connected=state.wallet_connections.includes(p.canonical_participant_id);
  if(scenario.stage!=='wallet'){$('#ack').innerHTML=product.ackOffer();return;}
  $('#ack').innerHTML='<button class="close" data-action="dismiss" aria-label="Close and continue off-chain">×</button><span class="eyebrow">OPTIONAL PARTICIPATION</span><h2 id="ack-title">Record your participation acknowledgement</h2>'+product.walletHeading(connected,scenario.connecting,connectionError)+'<div class="notice">'+sponsorshipMarkup(model.gasPolicy(state,q.question_id))+'</div>'+(connectionError?'<p class="notice error" role="alert">The demo connection failed. Your question is saved. Retry the connection or continue off-chain.</p>':'')+'<details id="ack-scenarios"'+(scenario.expanded?' open':'')+'><summary>Reviewer test scenarios</summary><label for="connect-outcome">Connection outcome</label><select id="connect-outcome"'+(scenario.connecting?' disabled':'')+'>'+outcomeOptions(scenario.connect)+'</select><label for="ack-outcome">Acknowledgement outcome</label><select id="ack-outcome"'+(scenario.connecting?' disabled':'')+'>'+outcomeOptions(scenario.ack)+'</select></details><p class="small">No real wallet, signature, payment or blockchain transaction is used. A receipt cannot establish question qualification or validate project claims.</p><div class="actions"><button class="button" data-action="'+(connected?'acknowledge':'connect')+'"'+(scenario.connecting?' disabled aria-busy="true"':'')+'>'+(connected?'Record demo acknowledgement':scenario.connecting?'Connecting…':connectionError?'Retry connection':'Connect Wallet')+'</button><button class="button secondary" data-action="offchain">Continue off-chain</button></div>';
}
function openAck(retry=false){connectionError=false;const scenario=ackScenario(ackScenarios,qCurrent());scenario.stage=retry?'wallet':'offer';renderAck();displayAckDialog('ack');}
function closeAck(){modalOpen=false;ackDialogId=null;for(const id of ['ack','sponsorship','kyc'])if($('#'+id).open)$('#'+id).close();}
function offchain(source){model.continueOffchain(state,currentId,source);closeAck();page='confirmation';render();}
function saveVisibleDraft(){if(page!=='question')return;const text=$('#question-text').value;model.saveDraft(state,text,$('#section').value);$('#draft-status').textContent='✓ Draft saved';$('#question-count').textContent=characterCount(text);$('#question-count').setAttribute('data-limit-exceeded',String(text.length>2000));$('#question-error').textContent='';notebook();}
function discardAndExit(){if($('#discard').open)$('#discard').close();model.abandon(state);editingId=null;page='eligibility';render();}
function inlineConfirmation(id,message){render({focusMain:false});$('#'+id).textContent=message;$('#'+id).focus({preventScroll:true});}
const actions={
  choose(){ $('#accounts').innerHTML=product.accounts();$('#accounts').showModal(); },
  'close-accounts'(){ $('#accounts').close(); },
  register(alias){model.register(state,alias);if($('#accounts').open)$('#accounts').close();page='eligibility';editingId=null;currentId=null;render();},
  switch(){actions.choose();},journey(){page=state.active_participant_id?'eligibility':'join';render();},
  disclosure(){model.openDisclosure(state);page='disclosure';render();},
  question(){model.beginQuestion(state);page='question';render();$('#question-text').focus();},
  back(){saveVisibleDraft();model.openDisclosure(state,true);page='disclosure';render();},
  abandon(){saveVisibleDraft();if(meaningfulDraft(state.drafts[state.active_participant_id]))$('#discard').showModal();else discardAndExit();},
  'keep-editing'(){ $('#discard').close();if(page==='question')$('#question-text').focus({preventScroll:true}); },
  discard(){discardAndExit();},
  another(){model.beginQuestion(state);editingId=null;currentId=null;page='question';render();$('#question-text').focus();},
  done(){model.completeSession(state);page='done';render();},
  queue(){page='queue';render();},dashboard(){page='dashboard';render();},
  'ack-proceed'(){const p=model.participant(state),scenario=ackScenario(ackScenarios,qCurrent());if(p.kyc_demo_status!=='verified'&&!scenario.kycSkipped){$('#sponsorship').innerHTML=product.feeDialog();displayAckDialog('sponsorship');}else{scenario.stage='wallet';renderAck();displayAckDialog('ack');}},
  'kyc-info'(){ $('#kyc').innerHTML=product.kycDialog();displayAckDialog('kyc'); },
  'back-sponsorship'(){ $('#sponsorship').innerHTML=product.feeDialog();displayAckDialog('sponsorship'); },
  'without-kyc'(){const scenario=ackScenario(ackScenarios,qCurrent());scenario.kycSkipped=true;scenario.stage='wallet';renderAck();displayAckDialog('ack');},
  async connect(){
    const q=qCurrent(),scenario=rememberAckScenario(),version=q.version;if(scenario.connecting)return;scenario.connecting=true;renderAck();
    await new Promise(resolve=>setTimeout(resolve,350));scenario.connecting=false;
    if(!state.questions.includes(q)||q.version!==version||state.active_participant_id!==q.canonical_participant_id||q.wallet_decision==='off_chain'||!modalOpen)return;
    connectionError=!model.connectWallet(state,q.question_id,scenario.connect);renderAck();notebook();
  },
  acknowledge(){rememberAckScenario();const attempt=model.acknowledge(state,currentId,ackScenario(ackScenarios,qCurrent()).ack);closeAck();page=attempt.outcome==='success'?'ack-result':'confirmation';render();},
  retry(){model.retryAcknowledgement(state,currentId);page='saved';render();openAck(true);},
  offchain(){offchain('continue_off_chain');},dismiss(){offchain('dismiss_button');},
  revise(){const q=qCurrent();editingId=q.question_id;model.saveDraft(state,q.text,q.disclosure_section_id);page='question';render();},
  'show-question'(id){const q=ownQuestions().find(q=>q.question_id===id);if(!q)throw Error('Select the participant who owns this question.');currentId=id;editingId=null;page='confirmation';render();},
  'show-current'(){const q=ownQuestions().at(-1);if(q){currentId=q.question_id;page='confirmation';}else page=state.active_participant_id?'eligibility':'join';render();},
  certificate(id){const c=model.certificateRecord(state,id);$('#certificate-content').innerHTML=certificateMarkup(c);$('#certificate').showModal();}
};
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;notify('');try{const result=actions[button.dataset.action]?.(button.dataset.id);if(result?.catch)return result.catch(error=>notify(error.message));return result;}catch(error){notify(error.message);}});
$('#brand').addEventListener('click',event=>{event.preventDefault();actions.journey();});
$('#main').addEventListener('input',event=>{if(page==='question'&&['question-text','section'].includes(event.target.id))saveVisibleDraft();});
$('#main').addEventListener('change',event=>{if(event.target.id==='review-question'){queueId=event.target.value;render();}if(event.target.id==='review-status'){$('#review-reason').innerHTML=reasonOptions(event.target.value,$('#review-reason').value);$('#qualification-checklist').hidden=event.target.value!=='qualified';}});
$('#ack').addEventListener('change',event=>{if(['connect-outcome','ack-outcome'].includes(event.target.id))rememberAckScenario();});
$('#main').addEventListener('submit',event=>{event.preventDefault();notify('');try{
  if(event.target.id==='question-form'){const result=editingId?model.reviseQuestion(state,editingId,$('#question-text').value,$('#section').value):model.submitQuestion(state,$('#question-text').value,$('#section').value);if(!result.ok){$('#question-error').textContent=result.message;notebook();return;}currentId=result.question.question_id;editingId=null;page='saved';render();openAck();}
  if(event.target.id==='review-form'){const q=model.reviewQuestion(state,event.target.dataset.id,{decision:$('#review-status').value,reason_code:$('#review-reason').value,reason_note:$('#review-note').value,criteria:$('#review-status').value==='qualified'?{material:$('#material').checked,actionable:$('#actionable').checked,not_spam:$('#not-spam').checked}:{}});inlineConfirmation('review-feedback','✓ Review decision saved — Question '+label(q.review_status).toLowerCase());}
  if(event.target.id==='followup-form'){const status=$('#followup-status').value,owner=$('#followup-owner').value;model.setFollowup(state,event.target.dataset.id,{status,owner,next_action:$('#next-action').value});inlineConfirmation('followup-feedback','✓ Follow-up saved — '+label(status)+' and assigned to '+ownerLabel(owner));}
}catch(error){notify(error.message);}});
for(const id of ['ack','sponsorship','kyc']){const dialog=$('#'+id);dialog.addEventListener('cancel',event=>{event.preventDefault();offchain('escape_dismissal');});dialog.addEventListener('close',()=>{if(modalOpen&&ackDialogId===id&&!dialog.open)offchain('dialog_dismissal');});}
$('#discard').addEventListener('cancel',event=>{event.preventDefault();actions['keep-editing']();});
$('#close-certificate').addEventListener('click',()=>$('#certificate').close());$('#print-certificate').addEventListener('click',()=>window.print());
$('#reset').addEventListener('click',()=>{closeAck();for(const id of ['certificate','accounts','discard'])if($('#'+id).open)$('#'+id).close();state=model.createSession();ackScenarios.clear();page='join';currentId=null;editingId=null;queueId=null;notify('Live sandbox reset. Experiment snapshot unchanged.');render();});
try{const response=await fetch('../data/experiment.synthetic.json');if(!response.ok)throw Error('Cannot load local experiment fixture. Start the documented server.');snapshot=await response.json();render();}catch(error){$('#main').textContent=error.message;}
